<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { intelligenceApi, type IntelligenceEvent } from '@/api/intelligence'
import EmptyState from '@/components/common/EmptyState.vue'
import LoadingState from '@/components/common/LoadingState.vue'

const router = useRouter(), events = ref<IntelligenceEvent[]>([]), total = ref(0), loading = ref(false), clustering = ref(false)
const tab = ref('latest'), sort = ref('latest'), selected = ref<string[]>([]), mergeOpen = ref(false), targetId = ref(''), keepTitle = ref('')
const tabs = [{id:'hot',label:'热点'},{id:'latest',label:'最新'},{id:'risk',label:'风险'},{id:'rising',label:'升温'},{id:'responded',label:'已回应'},{id:'closed',label:'已结束'}]
async function load(){loading.value=true;try{const data=await intelligenceApi.events({tab:tab.value,sort:sort.value,page_size:50});events.value=data.items;total.value=data.total;selected.value=[]}finally{loading.value=false}}
async function cluster(){clustering.value=true;try{const result=await intelligenceApi.clusterEvents();ElMessage.success(`扫描 ${result.scanned_count} 条内容，新建 ${result.created_count} 个事件`);await load()}finally{clustering.value=false}}
function toggle(id:string){selected.value=selected.value.includes(id)?selected.value.filter(item=>item!==id):[...selected.value,id]}
function prepareMerge(){if(selected.value.length<2)return;targetId.value=selected.value[0];keepTitle.value=events.value.find(item=>item.id===targetId.value)?.title||'';mergeOpen.value=true}
async function merge(){await intelligenceApi.mergeEvents({target_event_id:targetId.value,source_event_ids:selected.value.filter(id=>id!==targetId.value),keep_title:keepTitle.value});mergeOpen.value=false;ElMessage.success('事件已合并并写入审计日志');await load()}
function date(value:string|null){return value?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'时间未知'}
function statusName(status:string){return {detected:'已发现',rising:'升温',responded:'已回应',closed:'已结束'}[status]||status}
onMounted(load)
</script>
<template><div class="events-page"><header class="events-head page-shell"><div><p class="eyebrow">EVENT INTELLIGENCE</p><h1>事件中心</h1><span>把分散内容聚合成可研究、可修正的事件。</span></div><div><button v-if="selected.length>=2" type="button" @click="prepareMerge">合并 {{ selected.length }} 个事件</button><button class="primary" type="button" :disabled="clustering" @click="cluster"><el-icon><MagicStick /></el-icon>{{ clustering?'聚类中':'运行事件聚类' }}</button></div></header><main class="page-shell"><nav class="tabs"><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id;load()">{{ item.label }}</button><span>{{ total }} 个事件</span><select v-model="sort" @change="load"><option value="latest">最近活动</option><option value="heat">热度最高</option><option value="risk">风险最高</option></select></nav><LoadingState v-if="loading" label="正在读取事件"/><EmptyState v-else-if="!events.length" title="当前没有事件" description="先同步真实数据，再运行事件聚类。"/><section v-else class="event-list"><article v-for="event in events" :key="event.id"><label class="check"><input type="checkbox" :checked="selected.includes(event.id)" @change="toggle(event.id)"/><i></i></label><button class="event-main" type="button" @click="router.push(`/events/${event.id}`)"><div class="event-top"><span :class="`status ${event.status}`">{{ statusName(event.status) }}</span><em>{{ event.category }}</em><time>{{ date(event.last_activity_at) }}</time></div><h2>{{ event.title }}</h2><p>{{ event.summary||'暂无摘要' }}</p><footer><span>内容 <b>{{ event.content_count }}</b></span><span>来源 <b>{{ event.source_count }}</b></span><span>可信度 <b>{{ Math.round(event.confidence) }}</b></span><span v-if="event.manual_locked" class="locked">人工锁定</span></footer></button><div class="scores"><div><span>热度</span><strong>{{ Math.round(event.heat_score) }}</strong><i><b :style="{width:`${event.heat_score}%`}"></b></i></div><div class="risk"><span>风险</span><strong>{{ Math.round(event.risk_score) }}</strong><i><b :style="{width:`${event.risk_score}%`}"></b></i></div></div></article></section></main><div v-if="mergeOpen" class="overlay" @click.self="mergeOpen=false"><form class="modal" @submit.prevent="merge"><h2>合并事件</h2><p>所有来源内容将移入目标事件，其他事件会软关闭并保留审计记录。</p><label>目标事件<select v-model="targetId"><option v-for="event in events.filter(item=>selected.includes(item.id))" :key="event.id" :value="event.id">{{ event.title }}</option></select></label><label>保留标题<input v-model="keepTitle" required/></label><footer><button type="button" @click="mergeOpen=false">取消</button><button class="primary">确认合并</button></footer></form></div></div></template>
<style scoped>
.events-page{min-height:100vh;background:#f3f6f5}.events-head{padding-top:36px;padding-bottom:24px;display:flex;align-items:end;justify-content:space-between;border-bottom:1px solid #d5dfdb}.events-head h1{margin:0;font-size:35px}.events-head span{display:block;margin-top:7px;color:#73847e;font-size:12px}.events-head>div:last-child{display:flex;gap:8px}.events-head button{min-height:42px;padding:0 14px;border:1px solid #ccd8d3;border-radius:5px;background:white}.events-head .primary,.modal .primary{border-color:#167f76;color:white;background:#167f76}.tabs{height:54px;display:flex;align-items:center;gap:3px;border-bottom:1px solid #d3ddd9}.tabs button{height:36px;padding:0 13px;border:0;border-radius:4px;color:#657770;background:transparent}.tabs button.active{color:#126f67;background:#e4f2ef;font-weight:750}.tabs span{margin-left:auto;color:#81908b;font-size:10px}.tabs select{height:34px;margin-left:8px;border:1px solid #cbd6d2;background:white}.event-list{display:grid;gap:9px}.event-list article{min-height:156px;padding:18px;display:grid;grid-template-columns:24px minmax(0,1fr) 190px;gap:14px;align-items:center;border:1px solid #d4dedb;border-radius:7px;background:white}.check{align-self:start}.check input{position:absolute;opacity:0}.check i{width:17px;height:17px;border:1px solid #aebdb7;border-radius:3px;display:block}.check input:checked+i{border-color:#167f76;background:#167f76;box-shadow:inset 0 0 0 4px white}.event-main{border:0;background:transparent;text-align:left;cursor:pointer}.event-top{display:flex;align-items:center;gap:8px}.event-top time{margin-left:auto;color:#84928d;font-size:9px}.status,.event-top em{padding:3px 6px;border-radius:3px;color:#5b7169;background:#edf2f0;font-size:9px;font-style:normal}.status.rising{color:#a2670b;background:#fff2d4}.status.responded{color:#176e9c;background:#e7f4fb}.status.closed{color:#707b77;background:#ecefee}.event-main h2{margin:10px 0 6px;font-size:19px}.event-main p{margin:0;color:#687a74;font-size:11px;line-height:1.65}.event-main footer{margin-top:15px;display:flex;gap:15px;color:#87958f;font-size:9px}.event-main footer b{color:#314b43}.event-main .locked{color:#16776e}.scores{padding-left:18px;border-left:1px solid #e0e6e3;display:grid;grid-template-columns:1fr 1fr;gap:14px}.scores div{display:grid;gap:4px}.scores span{color:#80908a;font-size:9px}.scores strong{font:650 25px Georgia,serif}.scores i{height:3px;background:#e5ebe8}.scores i b{height:100%;display:block;background:#239489}.scores .risk i b{background:#dc625b}.overlay{position:fixed;inset:0;z-index:500;display:grid;place-items:center;background:rgba(10,25,20,.4)}.modal{width:min(500px,calc(100vw - 28px));padding:24px;border-radius:7px;background:white}.modal h2{margin:0}.modal>p{color:#71817c;font-size:11px}.modal label{margin-top:16px;display:grid;gap:6px;font-size:11px}.modal input,.modal select{height:40px;padding:0 9px;border:1px solid #ccd7d3}.modal footer{margin-top:24px;display:flex;justify-content:flex-end;gap:8px}.modal footer button{height:38px;padding:0 14px;border:1px solid #ccd7d3;border-radius:4px;background:white}@media(max-width:760px){.events-head{align-items:flex-start;flex-direction:column;gap:18px}.tabs{overflow-x:auto}.tabs span{display:none}.event-list article{grid-template-columns:20px 1fr}.scores{grid-column:2;border-left:0;padding:0;max-width:220px}.event-top time{display:none}}
</style>
